1	import { readFileSync } from 'node:fs';
2	import { basename, join } from 'node:path';
3	import {
4		BUDGETS,
5		CODEX_VERSION,
6		EVIDENCE_ID,
7		MODEL,
8		ORDER,
9		SYSTEM_INSTRUCTION,
10		TASKS,
11		V2_EVIDENCE_ID,
12		V3_BUDGETS,
13		V3_EVIDENCE_ID,
14		V4_EVIDENCE_ID,
15		V4_ORDER,
16		V4_SYSTEM_INSTRUCTION,
17		V5_EVIDENCE_ID,
18		V5_ORDER,
19		V5_TASKS,
