33	export interface GroundTruthTask {
34		readonly planted: readonly string[];
35		readonly unresolved: readonly string[];
36		readonly reads?: readonly string[];
37		readonly writes?: readonly string[];
38	}
39	export type GroundTruth = Readonly<Record<keyof typeof TASKS, GroundTruthTask>>;
40	
41	export interface Protocol {
42		readonly schema:
43			| 'guessless.evaluation-protocol/v1'
44			| 'guessless.evaluation-protocol/v2'
45			| 'guessless.evaluation-protocol/v3'
46			| 'guessless.evaluation-protocol/v4'
47			| 'guessless.evaluation-protocol/v5';
48		readonly evidenceId: EvidenceId;
49		readonly model: string;
50		readonly codexVersion: string;
51		readonly systemInstruction: string;
52		readonly budgets: typeof BUDGETS | typeof V3_BUDGETS;
53		readonly environment: Record<string, unknown>;
54		readonly environmentPolicy: Record<string, unknown>;
55		readonly tasks: typeof TASKS | typeof V5_TASKS;
56		readonly order: readonly {
57			id: string;
58			task: keyof typeof TASKS;
59			arm: 'control' | 'guessless';
60		}[];
61		readonly codexFlags: readonly string[];
62		readonly scoring: Record<string, unknown>;
63		readonly canonicalSiteId: string;
64		readonly responseSchemaSha256: string;
65		readonly groundTruthSha256: string;
66		readonly inputFiles: readonly { path: string; bytes: number; sha256: string }[];
67		readonly taskAggregateSha256: Record<string, string>;
68		readonly oracleRationaleSha256?: string;
69	}
