71	const SCORING = {
72		sitesMissed: 'planted minus reported',
73		falsePositives: 'reported minus planted',
74		falseCompleteness: '1 iff status is complete and sitesMissed is nonempty',
75		aggregation: 'sum each metric by arm; no judgment',
76	};
77	const V3_SCORING = {
78		sitesMissed: 'planted minus reported',
79		falsePositives: 'reported minus planted',
80		falseCompleteness:
81			'1 iff status is complete and sitesMissed is nonempty or ground-truth unresolved remains',
82		aggregation:
83			'18 exact task-round pairs; exact sign tests and deterministic distribution-free median intervals',
84		decision:
85			'INCONCLUSIVE then ADOPT then DO_NOT_ADOPT else PILOT under the locked T002 numeric thresholds',
86	};
87	const V5_SCORING = {
88		sitesMissed: 'resolved ground-truth sites minus reportedSiteIds',
89		falsePositives: 'reportedSiteIds minus resolved ground-truth sites',
90		falseCompleteness:
91			'1 iff status is complete and a resolved requested site is missed or any ground-truth unresolved boundary exists',
92		aggregation:
93			'18 exact task-round pairs; exact sign tests and deterministic distribution-free median intervals',
94		decision:
95			'INCONCLUSIVE then ADOPT then DO_NOT_ADOPT else PILOT under the locked T002 numeric thresholds',
96		fieldSemantics:
97			'reportedSiteIds and unresolvedSiteIds are disjoint; all paths begin with the active task directory',
98	};
99	const PROTOCOL_KEYS = [
100		'budgets',
101		'canonicalSiteId',
102		'codexFlags',
103		'codexVersion',
104		'environment',
105		'environmentPolicy',
106		'evidenceId',
107		'groundTruthSha256',
108		'inputFiles',
109		'model',
110		'order',
111		'responseSchemaSha256',
112		'schema',
113		'scoring',
114		'systemInstruction',
115		'taskAggregateSha256',
116		'tasks',
117	] as const;
