119	export function loadGroundTruth(fixtureRoot: string = paths().fixtureRoot): GroundTruth {
120		return validateGroundTruth(
121			JSON.parse(readFileSync(join(fixtureRoot, 'ground-truth.json'), 'utf8')),
122			basename(fixtureRoot) === V5_EVIDENCE_ID,
123		);
124	}
125	
126	function exactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
127		return stableJson(Object.keys(value).sort()) === stableJson([...expected].sort());
128	}
129	
130	function exactStringSet(value: unknown, label: string): string[] {
131		if (!Array.isArray(value) || !value.every((item) => typeof item === 'string'))
132			throw new Error(`${label} must be a string array`);
133		if (new Set(value).size !== value.length) throw new Error(`${label} contains duplicates`);
134		return [...value].sort();
135	}
136	
137	function validateGroundTruth(value: unknown, v5 = false): GroundTruth {
138		if (value === null || typeof value !== 'object' || Array.isArray(value))
139			throw new Error('ground truth must be an object');
140		const root = value as Record<string, unknown>;
141		if (!exactKeys(root, ['rename', 'delete', 'reach']))
142			throw new Error('ground truth task keys mismatch');
143		const normalized: Record<string, GroundTruthTask> = {};
144		for (const task of Object.keys(TASKS) as (keyof typeof TASKS)[]) {
145			const candidate = root[task];
146			if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate))
147				throw new Error(`${task} ground truth must be an object`);
148			const record = candidate as Record<string, unknown>;
149			const keys =
150				task === 'delete'
151					? [v5 ? 'resolved' : 'planted', 'reads', 'writes', 'unresolved']
152					: [v5 ? 'resolved' : 'planted', 'unresolved'];
153			if (!exactKeys(record, keys)) throw new Error(`${task} ground truth keys mismatch`);
154			const planted = exactStringSet(
155				v5 ? record.resolved : record.planted,
156				`${task}.${v5 ? 'resolved' : 'planted'}`,
157			);
158			const unresolved = exactStringSet(record.unresolved, `${task}.unresolved`);
159			if (!v5 && unresolved.some((id) => !planted.includes(id)))
160				throw new Error(`${task} unresolved category is outside planted set`);
161			if (v5 && unresolved.some((id) => planted.includes(id)))
162				throw new Error(`${task} resolved/unresolved truth overlap`);
163			if (task === 'delete') {
164				const reads = exactStringSet(record.reads, 'delete.reads');
165				const writes = exactStringSet(record.writes, 'delete.writes');
166				const categories = [...reads, ...writes, ...(v5 ? [] : unresolved)].sort();
167				if (
168					new Set(categories).size !== categories.length ||
169					stableJson(categories) !== stableJson(planted)
170				)
171					throw new Error('delete category mismatch');
172				normalized[task] = { planted, reads, writes, unresolved };
173			} else normalized[task] = { planted, unresolved };
174		}
175		return normalized as GroundTruth;
176	}
