182	export function validateProtocol(
183		protocol: unknown,
184		fixtureRoot: string,
185		inputRoot: string = join(fixtureRoot, 'input'),
186	): Protocol {
187		if (protocol === null || typeof protocol !== 'object' || Array.isArray(protocol))
188			throw new Error('authoritative protocol must be an object');
189		const value = protocol as Protocol;
190		const evidenceId = basename(fixtureRoot);
191		if (
192			![EVIDENCE_ID, V2_EVIDENCE_ID, V3_EVIDENCE_ID, V4_EVIDENCE_ID, V5_EVIDENCE_ID].includes(
193				evidenceId,
194			)
195		)
196			throw new Error('authoritative evaluation identity mismatch');
197		const expectedSchema = `guessless.evaluation-protocol/${
198			evidenceId === EVIDENCE_ID
199				? 'v1'
200				: evidenceId === V2_EVIDENCE_ID
201					? 'v2'
202					: evidenceId === V3_EVIDENCE_ID
203						? 'v3'
204						: evidenceId === V4_EVIDENCE_ID
205							? 'v4'
206							: 'v5'
207		}`;
208		const repeated = [V3_EVIDENCE_ID, V4_EVIDENCE_ID, V5_EVIDENCE_ID].includes(evidenceId);
209		const v5 = evidenceId === V5_EVIDENCE_ID;
210		const expectedResponseSchemaSha256 =
211			evidenceId === EVIDENCE_ID
212				? '045ad581eafe18fa350bf628a7a74094f5e190d9dbcb0d8b5d12feac6a540569'
213				: '0f17b96d34ac989198ced68ef9ebe9ba6c70cafa5cf488e2755ccb4a5a3b66f3';
214		if (
215			stableJson(Object.keys(value).sort()) !==
216				stableJson(v5 ? [...PROTOCOL_KEYS, 'oracleRationaleSha256'].sort() : PROTOCOL_KEYS) ||
217			value.schema !== expectedSchema ||
218			value.evidenceId !== evidenceId ||
219			value.model !== MODEL ||
220			value.codexVersion !== CODEX_VERSION ||
221			value.systemInstruction !==
222				(evidenceId === V4_EVIDENCE_ID || v5 ? V4_SYSTEM_INSTRUCTION : SYSTEM_INSTRUCTION) ||
223			stableJson(value.budgets) !== stableJson(repeated ? V3_BUDGETS : BUDGETS) ||
224			stableJson(value.tasks) !== stableJson(v5 ? V5_TASKS : TASKS) ||
225			stableJson(value.order) !== stableJson(v5 ? V5_ORDER : repeated ? V4_ORDER : ORDER) ||
226			stableJson(value.environment) !==
227				stableJson({ node: 'v24.15.0', pnpm: '10.33.2', os: 'Darwin-arm64-25.5.0' }) ||
228			stableJson(value.environmentPolicy) !==
229				stableJson({
230					allowlistedNames: ['HOME', 'LANG', 'PATH', 'TMPDIR'],
231					fixedValues: { LANG: 'C.UTF-8', PATH: '/usr/bin:/bin:/usr/sbin:/sbin' },
232					hashedValueNames: ['HOME', 'TMPDIR'],
233					forbiddenNamePattern: '(?i)(secret|token|key|password|credential|auth|cookie)',
234				}) ||
235			stableJson(value.scoring) !==
236				stableJson(v5 ? V5_SCORING : repeated ? V3_SCORING : SCORING) ||
237			value.canonicalSiteId !==
238				(v5
239					? '<task>/<task-relative-posix-path>:<1-based-line>:<1-based-column> at the locked lexeme start; reported and unresolved fields are disjoint'
240					: '<fixture-relative-posix-path>:<1-based-line>:<1-based-column> at the exact queried symbol occurrence start') ||
241			stableJson(value.codexFlags) !==
242				stableJson([
243					'--ephemeral',
244					'--ignore-user-config',
245					'--ignore-rules',
246					'--skip-git-repo-check',
247					'--sandbox',
248					'read-only',
249					'--json',
250				]) ||
251			value.responseSchemaSha256 !==
252				(v5
253					? '8e42acaf9806f361d717d31ae1739acb97dcb8cdf2f4092a968728bf45ce9e91'
254					: expectedResponseSchemaSha256) ||
255			value.responseSchemaSha256 !== sha256File(join(fixtureRoot, 'response.schema.json')) ||
256			value.groundTruthSha256 !==
257				(v5
258					? '137d8170a850410fee154b1be17b05d6761bcb282d0a279c4f58689111478f22'
259					: 'dbf5a361045bb9707115898c7b5005b8067d533c79d7a1af17460b1e916d4655') ||
260			value.groundTruthSha256 !== sha256File(join(fixtureRoot, 'ground-truth.json')) ||
261			stableJson(value.inputFiles) !== stableJson(fileLedger(inputRoot)) ||
262			stableJson(value.taskAggregateSha256) !==
263				stableJson({
264					delete: aggregateHash(inputRoot, 'delete'),
265					reach: aggregateHash(inputRoot, 'reach'),
266					rename: aggregateHash(inputRoot, 'rename'),
267				}) ||
268			stableJson(value.taskAggregateSha256) !==
269				stableJson({
270					delete: '7f347f023d615d6398184b498d290c67d79e1686319584f6982f9a96c2e63f2d',
271					reach: '42f829712441794707c97086cde20b64f1175f5ab2cb5aa981da15144ab20a6d',
272					rename: '35c4d2ba925a247c7190a5a58f4a05546fecb9faff32b9c2401cf0e94b9a0a54',
273				}) ||
274			(v5 &&
275				(value.oracleRationaleSha256 !==
276					'98f91a25c7a44ed5a8a4d9e04336e3bd8c9b6b21bf0ebf2c51d6128f59ded389' ||
277					value.oracleRationaleSha256 !==
278						sha256File(join(fixtureRoot, 'oracle-rationale.json'))))
279		)
280			throw new Error('authoritative evaluation protocol mismatch');
281		return value;
282	}
283	
284	export function loadProtocol(fixtureRoot: string = paths().fixtureRoot): Protocol {
285		return validateProtocol(
286			JSON.parse(readFileSync(join(fixtureRoot, 'protocol.json'), 'utf8')),
287			fixtureRoot,
288		);
289	}
