291	type Node = { start: number; end: number; type: string; [key: string]: unknown };
292	type Symbol = { declarations: readonly Node[]; module: Module };
293	type Module = {
294		path: string;
295		source: string;
296		parentOf(node: Node): Node | null;
297		symbolOf(node: Node): (Symbol & { name: string }) | null;
298		imports: readonly {
299			isNamespace: boolean;
300			local: Symbol | null;
301			resolvedModule: Module | null;
302			node: Node;
303		}[];
304	};
305	
306	function positionId(task: keyof typeof TASKS, module: Module, node: Node): string {
307		if (!Number.isSafeInteger(node.start) || node.start < 0)
308			throw new Error('resolved anchor lacks an exact Yuku start');
309		const before = module.source.slice(0, node.start).split('\n');
310		return `${task}/${module.path}:${before.length}:${(before.at(-1)?.length ?? 0) + 1}`;
311	}
312	
313	function resolveNode(
314		engine: InstanceType<typeof GuesslessEngine>,
315		anchor: unknown,
316	): { module: Module; node: Node } {
317		const resolved = engine.resolve(anchor as never) as Node | Symbol | null;
318		if (resolved === null) throw new Error('receipt anchor did not resolve');
319		if ('declarations' in resolved) {
320			const symbol = resolved as Symbol;
321			if (symbol.declarations.length !== 1) throw new Error('receipt symbol is ambiguous');
322			return { module: symbol.module, node: symbol.declarations[0]! };
323		}
324		const file = (anchor as { file: string }).file;
325		const module = engine.module(file) as unknown as Module | undefined;
326		if (module === undefined) throw new Error('receipt site module missing');
327		return { module, node: resolved };
328	}
329	
330	function parentUntil(module: Module, node: Node, type: string): Node | null {
331		let current: Node | null = node;
332		while (current !== null) {
333			if (current.type === type) return current;
334			current = module.parentOf(current);
335		}
336		return null;
337	}
338	
339	function taskEngine(
340		inputRoot: string,
341		task: keyof typeof TASKS,
342	): InstanceType<typeof GuesslessEngine> {
343		const engine = new GuesslessEngine();
344		for (const file of fileLedger(join(inputRoot, task))) {
345			const added = engine.addFile(
346				file.path,
347				readFileSync(join(inputRoot, task, file.path), 'utf8'),
348			);
349			if ('schema' in added) throw new Error(`${task}/${file.path} was not accepted`);
350		}
351		engine.link();
352		return engine;
353	}
354	
355	function unique(values: readonly string[]): string[] {
356		const sorted = [...values].sort();
357		if (new Set(sorted).size !== sorted.length) throw new Error('duplicate resolved position ID');
358		return sorted;
359	}
360	
361	export function deriveGroundTruth(inputRoot: string): GroundTruth {
362		const renameEngine = taskEngine(inputRoot, 'rename');
363		const renameTarget = renameEngine.anchor('api.ts', 'sendTelemetry');
364		if (renameTarget === null) throw new Error('rename target anchor missing or ambiguous');
365		const renameReceipt = renameEngine.referencesOf(renameTarget);
366		if (!renameEngine.verify(renameReceipt) || renameReceipt.state !== 'complete')
367			throw new Error('rename receipt is not verified complete');
368		const rename = unique(
369			renameReceipt.results.map((result) => {
370				const { module, node } = resolveNode(renameEngine, result.site);
371				const member = module.parentOf(node);
372				const call = member?.type === 'MemberExpression' ? module.parentOf(member) : member;
373				if (call?.type !== 'CallExpression') throw new Error('rename reference is not a call');
374				return positionId('rename', module, node);
375			}),
376		);
377	
378		const deleteEngine = taskEngine(inputRoot, 'delete');
379		const deleteTarget = deleteEngine.anchor('state.ts', 'legacyFlag');
380		if (deleteTarget === null) throw new Error('delete target anchor missing or ambiguous');
381		const deleteReceipt = deleteEngine.referencesOf(deleteTarget);
382		if (!deleteEngine.verify(deleteReceipt) || deleteReceipt.state === 'refused')
383			throw new Error('delete receipt is not verified');
384		const reads: string[] = [];
385		const writes: string[] = [];
386		for (const result of deleteReceipt.results) {
387			const { module, node } = resolveNode(deleteEngine, result.site);
388			const id = positionId('delete', module, node);
389			if (result.access === 'read' || result.access === 'read-write') reads.push(id);
390			if (result.access === 'write' || result.access === 'read-write') writes.push(id);
391		}
392		const targetSymbol = deleteEngine.resolve(deleteTarget) as unknown as Symbol;
393		const unresolved: string[] = [];
394		for (const module of deleteEngine.analyzer.modules.values() as Iterable<Module>)
395			for (const imported of module.imports)
396				if (imported.resolvedModule === targetSymbol.module) {
397					let local = imported.local as (Symbol & { name: string }) | null;
398					if (local === null && imported.node.type === 'ImportExpression') {
399						const declarator = parentUntil(module, imported.node, 'VariableDeclarator');
400						const id = declarator?.id as Node | undefined;
401						local = id === undefined ? null : module.symbolOf(id);
402					}
403					if (
404						local === null ||
405						(!imported.isNamespace && imported.node.type !== 'ImportExpression')
406					)
407						continue;
408					const anchor = deleteEngine.anchor(module.path, local.name);
409					if (anchor === null) throw new Error('namespace anchor missing or ambiguous');
410					const receipt = deleteEngine.referencesOf(anchor);
411					if (!deleteEngine.verify(receipt) || receipt.state === 'refused')
412						throw new Error('namespace receipt is not verified');
413					for (const result of receipt.results) {
414						const resolved = resolveNode(deleteEngine, result.site);
415						const member = parentUntil(resolved.module, resolved.node, 'MemberExpression');
416						if (member !== null && member.computed === true) {
417							const property = member.property as Node | undefined;
418							if (property === undefined)
419								throw new Error('computed boundary property missing');
420							unresolved.push(positionId('delete', resolved.module, property));
421						}
422					}
423				}
424	
425		const reachEngine = taskEngine(inputRoot, 'reach');
426		const reachTarget = reachEngine.anchor('entry.ts', 'bootstrap');
427		if (reachTarget === null) throw new Error('reach target anchor missing or ambiguous');
428		const reachReceipt = reachEngine.reachableFrom(reachTarget);
429		if (!reachEngine.verify(reachReceipt) || reachReceipt.state === 'refused')
430			throw new Error('reach receipt is not verified');
431		const reachResults = reachReceipt.results.map((result) => ({
432			result,
433			...resolveNode(reachEngine, result.symbol),
434		}));
435		const boundarySymbols = new Set<unknown>();
436		const reachUnresolved: string[] = [];
437		for (const current of reachResults) {
438			for (const witness of current.result.witness) {
439				const site = resolveNode(reachEngine, witness);
440				if (parentUntil(site.module, site.node, 'ImportExpression') !== null) {
441					boundarySymbols.add(current.result.symbol);
442					reachUnresolved.push(positionId('reach', site.module, site.node));
443					const enclosing = parentUntil(site.module, site.node, 'FunctionDeclaration');
444					for (const candidate of reachResults)
445						if (enclosing !== null && candidate.node === (enclosing.id as Node | undefined))
446							boundarySymbols.add(candidate.result.symbol);
447				}
448			}
449		}
450		for (const gap of reachReceipt.state === 'partial' ? reachReceipt.unresolved : []) {
451			const site = resolveNode(reachEngine, gap.site);
452			reachUnresolved.push(positionId('reach', site.module, site.node));
453		}
454		const entry = resolveNode(reachEngine, reachTarget);
455		const reachable = [
456			positionId('reach', entry.module, entry.node),
457			...reachResults
458				.filter((item) => !boundarySymbols.has(item.result.symbol))
459				.map((item) => positionId('reach', item.module, item.node)),
460			...reachUnresolved,
461		];
462		return {
463			rename: { planted: rename, unresolved: [] },
464			delete: {
465				planted: unique([...reads, ...writes, ...unresolved]),
466				reads: unique(reads),
467				writes: unique(writes),
468				unresolved: unique(unresolved),
469			},
470			reach: { planted: unique(reachable), unresolved: unique(reachUnresolved) },
471		};
472	}
473	
474	export function proveGroundTruth(
475		fixtureRoot: string = paths().fixtureRoot,
476	): Record<string, unknown> {
477		loadProtocol(fixtureRoot);
478		const sources = fileLedger(join(fixtureRoot, 'input')).map((file) =>
479			readFileSync(join(fixtureRoot, 'input', file.path), 'utf8'),
480		);
481		if (sources.some((source) => /@site|rename:|delete:|reach:/.test(source)))
482			throw new Error('input contains an answer hint');
483		if (basename(fixtureRoot) === V5_EVIDENCE_ID) return proveIndependentGroundTruth(fixtureRoot);
484		const recordedValue = JSON.parse(readFileSync(join(fixtureRoot, 'ground-truth.json'), 'utf8'));
485		const derived = proveReceiptGroundTruth(recordedValue, join(fixtureRoot, 'input'));
486		return derived;
487	}
488	
489	export function proveIndependentGroundTruth(fixtureRoot: string): GroundTruth {
490		if (basename(fixtureRoot) !== V5_EVIDENCE_ID)
491			throw new Error('independent oracle is restricted to v5');
492		const truth = loadGroundTruth(fixtureRoot);
493		const rationale = JSON.parse(
494			readFileSync(join(fixtureRoot, 'oracle-rationale.json'), 'utf8'),
495		) as Record<string, unknown>;
496		if (
497			!exactKeys(rationale, [
498				'schema',
499				'method',
500				'forbiddenAuthorities',
501				'coordinateRule',
502				'sites',
503			]) ||
504			rationale.schema !== 'guessless.evaluation-independent-oracle/v1' ||
505			rationale.method !== 'fixed source bytes and documented lexemes only' ||
506			stableJson(rationale.forbiddenAuthorities) !==
507				stableJson([
508					'GuesslessEngine',
509					'any parser',
510					'oracle-part-3-v4 outputs',
511					'model outcomes',
512					'outcome-dependent tuning',
513				]) ||
514			rationale.coordinateRule !==
515				'UTF-8 fixture bytes interpreted as ASCII source; one-based line and one-based code-unit column at the documented lexeme start' ||
516			!Array.isArray(rationale.sites)
517		)
518			throw new Error('independent oracle rationale contract mismatch');
519		const expected = new Map<string, 'resolved' | 'unresolved'>();
520		for (const task of Object.keys(TASKS) as (keyof typeof TASKS)[]) {
521			for (const id of truth[task].planted) expected.set(id, 'resolved');
522			for (const id of truth[task].unresolved) expected.set(id, 'unresolved');
523		}
524		if (rationale.sites.length !== expected.size)
525			throw new Error('independent oracle rationale site count mismatch');
526		const observed = new Set<string>();
527		for (const unknownSite of rationale.sites) {
528			if (unknownSite === null || typeof unknownSite !== 'object' || Array.isArray(unknownSite))
529				throw new Error('independent oracle rationale site mismatch');
530			const site = unknownSite as Record<string, unknown>;
531			if (
532				!exactKeys(site, [
533					'id',
534					'field',
535					'sourceSha256',
536					'line',
537					'column',
538					'lexeme',
539					'lineText',
540				]) ||
541				typeof site.id !== 'string' ||
542				expected.get(site.id) !== site.field ||
543				observed.has(site.id) ||
544				typeof site.lexeme !== 'string' ||
545				site.lexeme.length === 0 ||
546				typeof site.lineText !== 'string' ||
547				typeof site.sourceSha256 !== 'string' ||
548				!Number.isSafeInteger(site.line) ||
549				!Number.isSafeInteger(site.column)
550			)
551				throw new Error('independent oracle rationale site fields mismatch');
552			const match = /^(rename|delete|reach)\/(.+):([1-9][0-9]*):([1-9][0-9]*)$/.exec(site.id);
553			if (match === null || Number(match[3]) !== site.line || Number(match[4]) !== site.column)
554				throw new Error(`${site.id} independent coordinate mismatch`);
555			const bytes = readFileSync(join(fixtureRoot, 'input', match[1]!, match[2]!));
556			if (bytes.some((byte) => byte > 0x7f) || sha256(bytes) !== site.sourceSha256)
557				throw new Error(`${site.id} fixed source bytes mismatch`);
558			const line = bytes.toString('utf8').split('\n')[Number(site.line) - 1];
559			const offset = Number(site.column) - 1;
560			if (
561				line !== site.lineText ||
562				line.slice(offset, offset + site.lexeme.length) !== site.lexeme ||
563				line.indexOf(site.lexeme) !== offset
564			)
565				throw new Error(`${site.id} locked lexeme mismatch`);
566			observed.add(site.id);
567		}
568		if (observed.size !== expected.size) throw new Error('independent oracle coverage mismatch');
569		return truth;
570	}
571	
572	export function proveReceiptGroundTruth(recordedValue: unknown, inputRoot: string): GroundTruth {
573		const derived = deriveGroundTruth(inputRoot);
574		const recorded = validateGroundTruth(recordedValue);
575		if (stableJson(derived) !== stableJson(recorded))
576			throw new Error('receipt-derived ground truth mismatch');
577		return derived;
578	}
