import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { GuesslessEngine } from '../../../../packages/engine/src/index.ts';

const inputRoot = process.argv[2]!;
const engine = new GuesslessEngine();
const files = ['api.ts', 'alias.ts', 'barrel.ts', 'direct.ts', 'higher-order.ts', 'namespace.ts'];
for (const file of files)
	engine.addFile(file, readFileSync(join(inputRoot, 'rename', file), 'utf8'));
engine.link();
const target = engine.anchor('api.ts', 'sendTelemetry')!;
const receipt = engine.referencesOf(target);
console.log('state', receipt.state, 'verify', engine.verify(receipt));
for (const r of receipt.results) {
	const site: any = r.site;
	const resolved: any = engine.resolve(site);
	const mod: any = engine.module(site.file);
	const node = 'declarations' in (resolved ?? {}) ? resolved.declarations[0] : resolved;
	const before = mod.source.slice(0, node.start).split('\n');
	const parent = mod.parentOf(node);
	console.log(
		JSON.stringify({
			file: site.file,
			semanticPath: site.semanticPath,
			access: r.access,
			pos: `${before.length}:${before.at(-1).length + 1}`,
			nodeType: node.type,
			parentType: parent?.type ?? null,
			text: mod.source.slice(node.start, node.end),
		}),
	);
}
console.log('unresolved', JSON.stringify((receipt as any).unresolved ?? []));

