node --input-type=module -e '
import { cpSync, mkdtempSync, writeFileSync, rmSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
const { deriveGroundTruth, loadProtocol } = await import("./packages/evaluation/src/fixtures.ts");
const { stableJson, sha256File } = await import("./packages/evaluation/src/contracts.ts");
const src = "packages/evaluation/fixtures/oracle-part-3-v1";
const temp = mkdtempSync(join(tmpdir(), "gt-probe-"));
const copy = join(temp, "oracle-part-3-v1");
cpSync(src, copy, { recursive: true });
const derived = deriveGroundTruth(join(copy, "input"));
writeFileSync(join(copy, "ground-truth.json"), stableJson(derived));
console.log("new sha256:", sha256File(join(copy, "ground-truth.json")));
try { loadProtocol(copy); console.log("protocol OK"); } catch (e) { console.log("protocol ERROR:", e.message); }
rmSync(temp, { recursive: true, force: true });
' --experimental-strip-types 2>&1 | tail -10
